<?php require __DIR__.'/app/bootstrap.php';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$st=db()->prepare("SELECT * FROM users WHERE email=? AND status='active' LIMIT 1");$st->execute([trim($_POST['email']??'')]);$u=$st->fetch();if($u&&password_verify($_POST['password']??'',$u['password_hash'])){$_SESSION['user']=['id'=>(int)$u['id'],'name'=>$u['name'],'email'=>$u['email'],'role'=>$u['role']];redirect($u['role']==='admin'?'admin.php':'reviewer.php');}flash('error','Credenciales incorrectas.');redirect('login.php');}render_header('Ingresar');?>
<div class="container py-5" style="max-width:520px"><div class="card card-body shadow-sm"><h1 class="h3">Ingresar</h1><form method="post"><?=csrf_field()?><label class="form-label mt-3">Correo</label><input class="form-control" type="email" name="email" required><label class="form-label mt-3">Contraseña</label><input class="form-control" type="password" name="password" required><button class="btn btn-primary w-100 mt-4">Ingresar</button></form></div></div><?php render_footer();?>